import re


def _result(action, speech, target=None):
    return {"action": action, "speech": speech, "target": target}


def interpret_utterance(command, hour, summaries):
    if not isinstance(command, str):
        raise TypeError("command must be a string")
    if not isinstance(hour, int) or isinstance(hour, bool) or not 0 <= hour <= 23:
        raise ValueError("hour must be from 0 through 23")

    text = command.strip().lower()
    words = re.findall(r"[a-z0-9]+", text)
    if not text:
        return _result("retry", "Please say that again.")

    if text.startswith("define "):
        topic = text[7:].strip()
        if topic in summaries:
            return _result("speak", summaries[topic], topic)
        return _result("missing", "I do not have that topic.")

    if text.startswith("play "):
        query = text[5:].strip()
        if not query:
            return _result("retry", "Please say that again.")
        return _result("play", f"Playing {query}.", query)

    destinations = {
        "open videos": ("videos", "https://video.invalid"),
        "open search": ("search", "https://search.invalid"),
        "open mail": ("mail", "https://mail.invalid"),
    }
    if text in destinations:
        name, target = destinations[text]
        return _result("open", f"Opening {name}.", target)

    if any(words[i:i + 2] == ["current", "hour"] for i in range(len(words) - 1)):
        return _result("speak", f"The hour is {hour:02d}:00.")

    if "hello" in words or "hi" in text:
        period = "morning" if hour < 12 else "afternoon" if hour < 18 else "evening"
        return _result("speak", f"Good {period}.")

    if text == "what are you doing":
        return _result("speak", "Waiting for your request.")
    if text == "how are you":
        return _result("speak", "Operating normally.")
    return _result("retry", "Please say that again.")

